                            jenkinsBuildNumber = parseInt(pathParts[i], 10);
                            break;
                        }
                        jenkinsJobPathParts.push(pathParts[i]);
                    }
                    if (jenkinsBuildNumber && jenkinsJobPathParts.length > 0) {
