                        if (typeof jenkinsRawLogs === 'string') {
                            try {
                                var jenkinsParsed = JSON.parse(jenkinsRawLogs);
                                if (jenkinsParsed && jenkinsParsed.result) jenkinsLogs = jenkinsParsed.result;
                            } catch (e) { /* use as-is */ }
                        }
                        appendLog(check, jenkinsLogs, 'Jenkins error log');
