    if (!mr) return mr;
    var sourceBranch = mr.source_branch || (mr.head && mr.head.ref) || '';
    var targetBranch = mr.target_branch || (mr.base && mr.base.ref) || '';
    var id = mr.iid || mr.number || mr.id;
    var htmlUrl = mr.web_url || mr.html_url || null;
