    var open = [];
    (inputThreads || []).forEach(function (t) {
        if (t && t.resolved !== true && t.bot !== true) open.push(t);
    });
    var targetedIds = {};
    (replies || []).forEach(function (r) {
        if (r && r.threadId) targetedIds[String(r.threadId)] = true;
    });
    var unaddressed = open.filter(function (t) {
        return !t.threadId || !targetedIds[String(t.threadId)];
    });
    return {
        openThreads: open,
        openCount: open.length,
        targetedCount: open.length - unaddressed.length,
        unaddressed: unaddressed
    };
}
