            [ghThread('PRRT_a', 1), ghThread('PRRT_b', 2), ghThread('PRRT_c', 3)],
            [{ threadId: 'PRRT_a', reply: 'one' }, { threadId: 'PRRT_b', reply: 'two' }, { threadId: 'PRRT_c', reply: 'three' }]
        );
        assert.equal(coverage.openCount, 3);
