        assert.contains(ci, 'No failed');

        var rs = h.files['input/PROJ-123/review_state.md'];
        assert.ok(rs && rs.trim().length > 0, 'review_state.md present and non-empty');
        assert.contains(rs, 'NONE', 'no concluded review → decision NONE');
