            { state: 'CHANGES_REQUESTED', commit_id: VERDICT_SHA, submitted_at: '2026-09-21T18:58:00Z' }
        ]);
        assert.equal(loaded.mod.headMovedSinceLastReview(verdict, prFixture()), true);
