var configModule = null;
var configLoaderModule = null;

// ── Test API (globals usable in test files) ──────────────────────────────────

function test(name, fn) {
    var fullName = _currentSuite_ + ' > ' + name;
    try {
        fn();
        _results_.passed++;
        console.log('  ✅ ' + fullName);
    } catch (e) {
        _results_.failed++;
