function buildOpenThreadAccountingBlock(m, liveOpen, inputThreads, unaddressed) {
    var inputKeys = threadKeySet(inputThreads);
    var unaddressedKeys = threadKeySet(unaddressed);
    var lines = liveOpen.map(function(t) {
