    });
    return { openCount: open.length, targetedCount: open.length - unaddressed.length, unaddressed: unaddressed };
}

function replyTargetsThread(r, t) {
    if (!r || !t) return false;
    if (t.threadId && r.threadId && String(t.threadId) === String(r.threadId)) return true;
    var tRoot = (t.rootCommentId !== null && t.rootCommentId !== undefined) ? String(t.rootCommentId) : null;
    if (!tRoot) return false;
    if (r.rootCommentId !== null && r.rootCommentId !== undefined && String(r.rootCommentId) === tRoot) return true;
    if (r.inReplyToId !== null && r.inReplyToId !== undefined && String(r.inReplyToId) === tRoot) return true;
    return false;
}
