function threadKeySetContains(keySet, t) {
    if (!t) return false;
    if (t.threadId && keySet[String(t.threadId)]) return true;
    if (t.rootCommentId !== null && t.rootCommentId !== undefined && keySet['c' + t.rootCommentId]) return true;
