 * rootCommentId (post-enrichment parity: postThreadReplies fills one id from
 * the other, so either id proves the thread was addressed). A null-threadId
 * reply with no rootCommentId (the live incident shape) targets nothing.
 */
function buildReplyCoverage(inputThreads, replies) {
    var open = (inputThreads || []).filter(isOpenThread);
    var targetedKeys = {};
    (replies || []).forEach(function(r) {
        if (!r) return;
        if (r.threadId) targetedKeys[String(r.threadId)] = true;
        if (r.rootCommentId !== null && r.rootCommentId !== undefined) targetedKeys['c' + r.rootCommentId] = true;
        if (r.inReplyToId !== null && r.inReplyToId !== undefined) targetedKeys['c' + r.inReplyToId] = true;
    });
    var unaddressed = open.filter(function(t) {
        var k = threadKeyOf(t);
        return !k || !targetedKeys[k];
    });
    return {
        openCount: open.length,
        targetedCount: open.length - unaddressed.length,
        unaddressed: unaddressed
    };
}","path":"js/pushReworkChanges.js"}

