    if (!hasThreadData && !inputContextFileExists(inputFolder + '/pr_discussions_raw.json')) {
        gitOps.writeInputFile(
            inputFolder + '/pr_discussions_raw.json',
            NO_THREADS_RAW_JSON,
            'pr_discussions_raw.json (contract placeholder — 0 threads at leg start)'
