    if (!hasFailures && !inputContextFileExists(inputFolder + '/ci_failures.md')) {
        gitOps.writeInputFile(
            inputFolder + '/ci_failures.md',
            CI_NO_FAILURES_MD,
            'ci_failures.md (contract placeholder — 0 failed checks at leg start)'
